import{_ as o,o as a,c as t,ag as s}from"./chunks/framework.DaCm-iTo.js";const b=JSON.parse('{"title":"Commands and Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/corelib/commands.md","filePath":"en/modules/corelib/commands.md","lastUpdated":null}'),n={name:"en/modules/corelib/commands.md"};function i(c,e,d,l,r,p){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="commands-and-permissions" tabindex="-1">Commands and Permissions <a class="header-anchor" href="#commands-and-permissions" aria-label="Permalink to &quot;Commands and Permissions&quot;">​</a></h1><p>The main command of EmakiCoreLib is <code>/emakicorelib</code>, with <code>/corelib</code> and <code>/emakicore</code> as aliases. These commands are mainly for server administrators: reloading CoreLib, running config prechecks, listing or executing registered Actions, and debugging loop Action tasks.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/corelib reload</code></td><td><code>emakicorelib.reload</code> or <code>emakicorelib.admin</code></td><td>Reload CoreLib configuration and the Action system. If precheck fails, the previous config remains active.</td></tr><tr><td><code>/corelib check [module|report|--fix]</code></td><td><code>emakicorelib.admin</code></td><td>Run config prechecks, check one module, or show the latest report. <code>--fix</code> is currently read-only and does not apply automatic fixes.</td></tr><tr><td><code>/corelib action list</code></td><td><code>emakicorelib.admin</code></td><td>List registered Actions with id, category, source, owner, execution mode, and parameter names.</td></tr><tr><td><code>/corelib action run &lt;actionId&gt; key=value ...</code></td><td><code>emakicorelib.admin</code></td><td>Execute one currently registered Action. <code>/corelib action &lt;actionId&gt; key=value ...</code> is also accepted as shorthand.</td></tr><tr><td><code>/corelib debug all [on|off|status]</code></td><td><code>emakicorelib.admin</code></td><td>Toggle the global Debug switch at runtime. Without an argument it behaves as <code>status</code>. A reload restores the configured <code>debug.global_all</code> value.</td></tr><tr><td><code>/corelib debug loops [list|player|key|cancel|cancel-player]</code></td><td><code>emakicorelib.admin</code></td><td>Inspect active loop Action tasks and cancel them by key or player.</td></tr><tr><td><code>/corelib help</code></td><td>none</td><td>Show subcommand help. Also shown when no argument or an unknown subcommand is given.</td></tr></tbody></table><p>The <code>action</code> subcommand may also be written as <code>actions</code>; both are equivalent.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>emakicorelib.reload</code></td><td>op</td><td>Allows CoreLib reload.</td></tr><tr><td><code>emakicorelib.admin</code></td><td>op</td><td>Administrative fallback permission; includes <code>emakicorelib.reload</code>.</td></tr></tbody></table><h2 id="common-operations" tabindex="-1">Common operations <a class="header-anchor" href="#common-operations" aria-label="Permalink to &quot;Common operations&quot;">​</a></h2><h3 id="reload-corelib" tabindex="-1">Reload CoreLib <a class="header-anchor" href="#reload-corelib" aria-label="Permalink to &quot;Reload CoreLib&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/corelib reload</span></span></code></pre></div><p>Use this after changing CoreLib configuration, language files, or Actions. Reload runs a config precheck first; if the precheck fails, the currently active configuration is kept.</p><h3 id="run-config-prechecks" tabindex="-1">Run config prechecks <a class="header-anchor" href="#run-config-prechecks" aria-label="Permalink to &quot;Run config prechecks&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/corelib check</span></span>
<span class="line"><span>/corelib check report</span></span>
<span class="line"><span>/corelib check corelib</span></span></code></pre></div><p><code>check</code> validates configuration references, Action templates, item sources, and CoreLib-related settings. <code>report</code> shows the latest precheck report. Passing a module id checks only that module.</p><h3 id="list-and-execute-registered-actions" tabindex="-1">List and execute registered Actions <a class="header-anchor" href="#list-and-execute-registered-actions" aria-label="Permalink to &quot;List and execute registered Actions&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/corelib action list</span></span>
<span class="line"><span>/corelib action run sendmessage text=&quot;hello&quot;</span></span></code></pre></div><p><code>action list</code> shows what is currently registered in the Action registry. <code>action run</code> parses <code>&lt;actionId&gt; key=value ...</code> as a normal Action line, so parameters, quoting, <code>@if</code>, <code>@chance</code>, and <code>@delay</code> follow the same rules as Action lines in configuration files. Console execution has no player context, so Actions that require a player fail through normal Action validation.</p><h3 id="debug-loop-actions" tabindex="-1">Debug loop Actions <a class="header-anchor" href="#debug-loop-actions" aria-label="Permalink to &quot;Debug loop Actions&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/corelib debug loops list</span></span>
<span class="line"><span>/corelib debug loops player Steve</span></span>
<span class="line"><span>/corelib debug loops key some-loop-key</span></span>
<span class="line"><span>/corelib debug loops cancel some-loop-key</span></span>
<span class="line"><span>/corelib debug loops cancel-player Steve</span></span></code></pre></div><p>These commands are for troubleshooting or cleaning up loop Actions. Do not keep large-scale loop task debugging enabled on production servers longer than necessary.</p><h3 id="toggle-global-debug" tabindex="-1">Toggle global Debug <a class="header-anchor" href="#toggle-global-debug" aria-label="Permalink to &quot;Toggle global Debug&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/corelib debug all status</span></span>
<span class="line"><span>/corelib debug all on</span></span>
<span class="line"><span>/corelib debug all off</span></span></code></pre></div><p>This has the same effect as temporarily overriding <code>debug.global_all</code> in <code>config.yml</code> and affects every Emaki module that uses CoreLib&#39;s <code>DebugLogger</code>. The toggle is not written back to the config file; <code>/corelib reload</code> restores the configured value.</p>`,23)])])}const m=o(n,[["render",i]]);export{b as __pageData,m as default};
